mapper.select:
SELECT id FROM article WHERE id > #{after} AND id <= #{upper}
AND hidden=FALSE
ORDER BY id LIMIT 500

SELECT a.id AS article_id,a.published_at,COALESCE(SUM(s.pv),0) AS views
FROM article a LEFT JOIN article_view_stat s
ON s.article_id=a.id AND s.stat_date BETWEEN #{from} AND #{to}
WHERE a.hidden=FALSE AND a.id IN
#{id}
GROUP BY a.id,a.published_at
